parameters.jsCode:
// Build a stage list for the UI
const stages = [
  { key: 'ingestion', label: 'Ingestion' },
  { key: 'cleaning', label: 'Cleaning' },
  { key: 'upload_overview', label: 'Upload Overview' },
  { key: 'quality', label: 'Quality' },
  { key: 'eda', label: 'EDA' },
  { key: 'preprocess', label: 'Preprocess' },
  { key: 'ml_ready', label: 'ML Ready' },
  { key: 'summary', label: 'Summary' },
  { key: 'performance', label: 'Performance Metrics' },
  { key: 'result', label: 'Result' }
];

const current = $json.current_stage || 'ingestion';
let foundCurrent = false;
const stageStatus = stages.map(s => {
  if (!foundCurrent) {
    if (s.key === current) {
      foundCurrent = true;
      return { ...s, status: 'current' };
    }
    return { ...s, status: 'completed' };
  }
  return { ...s, status: 'pending' };
});

return {
  ...$json,
  stages: stageStatus
};

// Universal Success Handler
const result = {
  message: "✅ Universal Pipeline Completed!",
  summary: "Your dataset has been automatically processed and analyzed.",
  run_id: $json.run_id,
  status: $json.status,
  auto_detected: $json.auto_detected_target ? {
    target_column: $json.auto_detected_target,
    message: "Target column was auto-detected"
  } : null,
  dataset_info: $json.dataset_info,
  outputs: $json.outputs,
  stages: $json.stages || [],
  download_links: {
    eda_report: `http://localhost:5000${$json.outputs?.eda_report}`,
    cleaned_data: `http://localhost:5000${$json.outputs?.cleaned_data}`,
    status_page: `http://localhost:5000/status/${$json.run_id}`
  },
  insights: [
    "Dataset automatically analyzed and preprocessed",
    "Target column detection applied", 
    "Data quality checks completed",
    "ML-ready outputs generated"
  ],
  supported_formats: ["CSV", "Excel", "JSON", "TXT"]
};

return result;

// Still Processing with Progress
const attempts = $node["Wait 15 Seconds"].context?.attempts || 0;
const result = {
  message: `⏳ Processing... (Attempt ${attempts + 1})`,
  run_id: $json.run_id,
  status: $json.status,
  current_stage: $json.current_stage || 'initial_processing',
  stages: $json.stages || [],
  elapsed_time: `${(attempts + 1) * 15} seconds`,
  next_check: "Waiting 15 seconds"
};

// Store attempt count
$node["Wait 15 Seconds"].context = { attempts: attempts + 1 };
return result;

